const MAX_BYTES = 8 * 1024 * 1024;
const ACTIONS: Record<FoldingAction, [string, string]> = { insufficient: ['证据不足', 'Insufficient evidence'], fold: ['合回主循环', 'Fold into main'], merge: ['合并专长分工', 'Merge specialists'], as_tool: ['作为结构化工具', 'Agent as tool'], keep: ['保留独立边界', 'Keep boundary'], main: ['保留主循环', 'Main loop'] };
const SOURCES: Record<FoldingSourceKind, [string, string]> = { official_recording: ['官方留存模型记录', 'Official recorded model run'], synthetic_traffic: ['生成流量', 'Generated traffic'], offline_smoke: ['离线流程验证 · 不评分', 'Offline smoke · unscored'], live_api: ['本地 API 执行记录', 'Local API execution'], user_import: ['用户导入 · 来源未认证', 'User import · provenance unverified'], native_telemetry: ['本地原生过程证据', 'Native retained telemetry'], source_code: ['源代码', 'Source code'] };
const STATES = { candidate: ['待检验候选', 'Audit candidate'], supported: ['本任务支持', 'Supported in this scope'], regression: ['有退步 · 阻止采纳', 'Regression · adoption blocked'], needs_evidence: ['需要补证据', 'Needs evidence'], protected: ['受保护边界', 'Protected boundary'], unscored: ['仅流程验证 · 不评分', 'Unscored smoke'] } as const;
const OUTCOMES = { both_passed: ['双方通过', 'Both pass'], regression: ['通过 → 失败', 'Pass → fail'], improvement: ['失败 → 通过', 'Fail → pass'], both_failed: ['双方失败', 'Both fail'], unknown: ['未知 / 缺失', 'Unknown / missing'] } as const;
const show = (value: number | null | undefined): string => value == null ? '—' : value.toLocaleString(undefined, { maximumFractionDigits: 2 });
const json = (value: unknown): string => JSON.stringify(value, null, 2);
function download(name: string, value: unknown): void {
  const url = URL.createObjectURL(new Blob([json(value)], { type: 'application/json' }));
  const link = document.createElement('a'); link.href = url; link.download = name; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function officialLink(value: string | null): string | undefined { return value && /^https:\/\//i.test(value) ? value : undefined; }
function defaultPlan(project: FoldingProject, boundaryId: string): FoldingRunPlan | null {
  const boundary = project.boundaries.find(item => item.id === boundaryId);
  if (!boundary || boundary.proposed === 'keep' || boundary.proposed === 'insufficient') return null;
  return { version: 1, kind: 'agent-folding-plan', title: `${project.title} · ${boundary.id}`, adapter: 'support-desk', provider: 'anthropic', model: null,
    boundaryId: boundary.id, operation: boundary.proposed, targetAgentIds: boundary.targetAgentIds, caseIds: project.cases.map(item => item.id), repetitions: 3, schedule: 'sequential',
    budgets: { maxCallsPerCase: 40, maxOutputTokens: 2048, maxInputChars: 200000, maxTotalTokensPerCase: 100000, timeoutMs: 120000, maxToolBatch: 8 }, external: null };
}
interface RequestOwner { controller: AbortController; timer: ReturnType<typeof setTimeout> }
interface ReaderOwner { reader: FileReader; timer: ReturnType<typeof setTimeout> }

/** Explicit retained-source reads and offline execution only. Paid plans are exported for the CLI. */
