  const [error, setError] = useState(''), [message, setMessage] = useState(''), [pending, setPending] = useState('');
  const [status, setStatus] = useState<FoldingProviderStatus | null>(null), [artifacts, setArtifacts] = useState<FoldingArtifact[] | null>(null);
  const [note, setNote] = useState(''), [humanAction, setHumanAction] = useState<FoldingHumanDecision['action']>('rerun');
  const [model, setModel] = useState(''), [reps, setReps] = useState(3), [tasks, setTasks] = useState<Array<{ id: string; title: string }>>([]), [nativeTaskId, setNativeTaskId] = useState('');
  const [advancedOpen, setAdvancedOpen] = useState(false), [includeConfirmation, setIncludeConfirmation] = useState(true), [skillAblation, setSkillAblation] = useState(true);
