  const [newCaseId, setNewCaseId] = useState(''), [newCaseTurns, setNewCaseTurns] = useState(['']), [newCaseCriteria, setNewCaseCriteria] = useState(''), [newCaseSplit, setNewCaseSplit] = useState<'train' | 'confirmation'>('train');
