  const decision = analysis?.decisions.find(item => item.boundaryId === selectedBoundary?.id);
  const experiments = project?.experiments.filter(item => item.boundaryId === selectedBoundary?.id) ?? [];
  const experiment = experimentId === '__planned' ? undefined : experiments.find(item => item.id === experimentId) ?? experiments[0];
  const result = analysis?.experiments.find(item => item.experimentId === experiment?.id);
