  const orderedCases = [...selectedCases].sort((a, b) => Number(result?.regressions.some(pair => pair.caseId === b.id) ?? false) - Number(result?.regressions.some(pair => pair.caseId === a.id) ?? false));
  const selectedCase = selectedCases.find(item => item.id === caseId) ?? orderedCases[0];
  const repetitions = [...new Set([...Array.from({ length: Math.max(1, experiment?.expectedRepetitions ?? 1) }, (_, n) => n), ...(result?.pairs.filter(pair => pair.caseId === selectedCase?.id).map(pair => pair.repetition) ?? [])])].sort((a, b) => a - b);
  const selectedPair = result?.pairs.find(item => item.caseId === selectedCase?.id && item.repetition === repetition);
  const selectedTrials = [selectedPair?.baselineTrialId, selectedPair?.candidateTrialId].map(id => project?.trials.find(trial => trial.id === id));
  const ablationTrial = experiment?.ablationVariantId ? project?.trials.find(trial => trial.experimentId === experiment.id && trial.variantId === experiment.ablationVariantId && trial.caseId === selectedCase?.id && trial.repetition === repetition) : undefined;
  const evidence = project?.evidence.find(item => item.id === evidenceId);
