      const nextCase = { id: newCaseId.trim(), title: newCaseId.trim(), turns: newCaseTurns.map(turn => turn.trim()), customerId: null, tags: ['user-defined'], checks: [{ id: 'independent-acceptance', kind: 'external' as const, expected: newCaseCriteria.trim(), required: true }], requiredChains: [], split: newCaseSplit, evidenceIds: [source.id] };
