      <details><summary>{text('任务输入、回答与动作参数', 'Task input, answer and action arguments')} · {trial.actions.length} {text('项动作', 'actions')}</summary><pre>{selectedCase?.turns.join('\n\n')}</pre><pre>{trial.answer ?? text('回答未记录', 'Answer not recorded')}</pre>{trial.actions.slice(0, 100).map((action, n) => <details key={`${action.name}/${n}`} className="af-action"><summary>{n + 1}. {action.name}</summary><pre>{json(action.args)}</pre>{action.evidenceId && refs([action.evidenceId])}</details>)}{trial.actions.length > 100 && <p>{text('仅显示前100项，完整动作见项目导出。', 'First 100 shown; all actions remain in the project export.')}</p>}</details>
